  async function runPatientIntegration(apply=false){ const result=await outcomeApi('/api/integration/patients/import',{method:'POST',body:JSON.stringify({rows:patientIntegrationRows,apply})}); const labels={CREATE:'新規候補',UNCHANGED:'一致',CONFLICT:'不一致',ERROR:'エラー'}; byId('patientIntegrationResult').innerHTML=`<div class="integration-counts">${Object.entries(result.counts||{}).map(([key,value])=>`<span>${labels[key]||key}<b>${value}</b></span>`).join('')}</div>${result.results?.filter(item=>item.status!=='UNCHANGED').length?`<div class="integration-issues">${result.results.filter(item=>item.status!=='UNCHANGED').slice(0,100).map(item=>`<article class="${item.status.toLowerCase()}"><strong>${escapeHtml(item.facilityPatientId||`行${item.row}`)}</strong><span>${escapeHtml(item.message)}</span></article>`).join('')}</div>`:'<p>差分はありません。</p>'}`; const blocked=(result.counts?.CONFLICT||0)+(result.counts?.ERROR||0)>0; byId('patientIntegrationApply').disabled=apply||blocked||!(result.counts?.CREATE>0); byId('patientIntegrationMessage').textContent=apply?`${result.created}人を新規登録しました。`:(blocked?'不一致・エラーを修正して再度プレビューしてください。':'安全確認済みです。新規患者だけ登録できます。'); if(apply)await loadOutcomeCenter(); await loadIntegrationRuns(); }
