  async function loadIntegrationRuns(){const [runs,backup,coverage]=await Promise.all([outcomeApi('/api/integration/patient-runs'),outcomeApi('/api/admin/backup-status'),outcomeApi('/api/integration/coverage')]);const typeLabel={PATIENT_CSV:'患者基本情報',CLINICAL_CSV:'病棟・診断・入退棟',REHAB_RECORD_CSV:'リハ実施記録',CLINICAL_EVENT_CSV:'処方・検査'};byId('integrationCoverage').innerHTML=`<div class="coverage-grid"><span>患者CSV<b>${coverage.coverage.patientCsv}%</b></span><span>病棟情報<b>${coverage.coverage.wardProfile}%</b></span><span>リハ実施<b>${coverage.coverage.rehabRecords}%</b></span><span>処方・検査<b>${coverage.coverage.clinicalEvents}%</b></span></div><div class="coverage-quality"><span>反映停止率 ${coverage.quality.blockedRate}%</span><span>重複防止 ${coverage.quality.duplicatesPrevented}件</span><span>不一致・エラー検出 ${coverage.quality.errorsDetected}件</span><strong>${coverage.target.status==='MEASURED_TARGET_MET'?'システム内カバー目標到達':'実証で時間削減率の測定が必要'}</strong></div><p>${escapeHtml(coverage.note)}</p>`;byId('integrationBackupStatus').innerHTML=`<div class="backup-status ${backup.latest?.encrypted?'safe':'warning'}"><strong>${backup.latest?`最終バックアップ ${escapeHtml(new Date(backup.latest.createdAt).toLocaleString('ja-JP'))}`:'バックアップ未作成'}</strong><span>${backup.latest?.encrypted?'暗号化済み':backup.latest?'暗号化状態を確認してください':'作成してください'}・保存 ${backup.count}世代</span><p>${escapeHtml(backup.restorePolicy)}</p></div>`;byId('integrationHistoryList').innerHTML=runs.length?runs.map(run=>`<article class="${run.status==='BLOCKED'?'blocked':'completed'}"><div><strong>${escapeHtml(typeLabel[run.type]||run.type)}｜${run.mode==='PREVIEW'?'プレビュー':'反映'}</strong><small>${escapeHtml(new Date(run.createdAt).toLocaleString('ja-JP'))}・${escapeHtml(run.createdBy||'')}</small></div><span>${run.status==='BLOCKED'?'停止':'完了'}</span><p>新規候補 ${run.counts?.CREATE||0}・一致 ${run.counts?.UNCHANGED||0}・不一致 ${run.counts?.CONFLICT||0}・エラー ${run.counts?.ERROR||0}・登録 ${run.created||0}</p>${run.issues?.length?`<details><summary>停止理由 ${run.issues.length}件</summary>${run.issues.map(issue=>`<p>${escapeHtml(issue.facilityPatientId||`行${issue.row}`)}：${escapeHtml(issue.message)}</p>`).join('')}</details>`:''}</article>`).join(''):'<p>連携履歴はありません。</p>';}
  async function loadPilotTimeSummary(){const data=await outcomeApi('/api/pilot/time-summary');byId('pilotTimeSummary').innerHTML=`<div class="coverage-grid">${data.workflows.map(item=>`<span>${escapeHtml(item.label)}<b>${item.reductionRate==null?'未比較':`${item.reductionRate}%`}</b><small>導入前 ${item.baselineAverage??'―'}分／試行中 ${item.trialAverage??'―'}分</small></span>`).join('')}</div><div class="coverage-quality"><strong>30％削減達成 ${data.targetMetWorkflows}／比較可能 ${data.comparableWorkflows}業務</strong></div><p>${escapeHtml(data.note)}</p>`;}
  async function loadPilotSafetySummary(){const data=await outcomeApi('/api/pilot/safety-summary');const labels={NEAR_MISS:'ヒヤリハット',PATIENT_MISMATCH:'患者取り違え',AI_PROPOSAL:'AI提案',SYSTEM:'システム障害',OTHER:'その他'};byId('pilotSafetySummary').innerHTML=`<div class="coverage-quality"><strong class="${data.gate.status==='MET'?'':'danger'}">${escapeHtml(data.gate.label)}：${data.gate.status==='MET'?'達成':'未達・試行停止確認'}</strong><span>全事象 ${data.counts.total}件</span><span>未解決 ${data.counts.open}件</span><span>重大 ${data.counts.serious}件</span><span>患者取り違え ${data.counts.patientMismatch}件</span></div>${data.events.length?data.events.map(item=>`<article class="${item.severity==='SERIOUS'?'blocked':'completed'}"><strong>${escapeHtml(item.occurredAt)}｜${escapeHtml(labels[item.category]||item.category)}｜${item.severity==='SERIOUS'?'重大':item.severity==='MEDIUM'?'中等度':'軽微'}</strong><p>${escapeHtml(item.description)}</p><small>${item.status==='RESOLVED'?'解決済み':'未解決'}・${escapeHtml(item.immediateAction||'直後対応未記載')}</small>${item.status==='OPEN'?`<button type="button" data-resolve-safety="${escapeHtml(item.id)}">原因・再発防止策を登録して解決</button>`:''}</article>`).join(''):'<p class="outcome-clear">安全事象の登録はありません。</p>'}<p>${escapeHtml(data.note)}</p>`;byId('pilotSafetySummary').querySelectorAll('[data-resolve-safety]').forEach(button=>button.addEventListener('click',async()=>{const resolution=window.prompt('原因と再発防止策を入力してください');if(!resolution)return;await outcomeApi(`/api/pilot/safety-events/${encodeURIComponent(button.dataset.resolveSafety)}`,{method:'PUT',body:JSON.stringify({status:'RESOLVED',resolution})});await loadPilotSafetySummary();}));}
  async function loadPilotFeedbackSummary(){const data=await outcomeApi('/api/pilot/staff-feedback-summary');byId('pilotFeedbackSummary').innerHTML=`<div class="coverage-grid"><span>回答数<b>${data.responses}人</b></span><span>継続意向<b>${data.agreementRate}%</b></span><span>使いやすさ<b>${data.averages.usability??'―'}/5</b></span><span>有用性<b>${data.averages.usefulness??'―'}/5</b></span><span>操作負荷<b>${data.averages.burden??'―'}/5</b></span></div><div class="coverage-quality"><strong>${escapeHtml(data.gate.label)}：${data.gate.status==='MET'?'達成':data.gate.status==='MORE_RESPONSES_REQUIRED'?'3人以上の回答が必要':'未達'}</strong><span>回答職種 ${data.roles.map(escapeHtml).join('・')||'未回答'}</span></div>${data.feedback.filter(item=>item.comment).length?`<h5>改善意見</h5>${data.feedback.filter(item=>item.comment).map(item=>`<p>${escapeHtml(item.staffRole)}：${escapeHtml(item.comment)}</p>`).join('')}`:''}<p>${escapeHtml(data.note)}</p>`;}
