  async function loadPilotStudy(){const data=await outcomeApi('/api/pilot/study');const labels={NOT_CONFIGURED:'未設定',PLANNED:'開始前',BASELINE:'導入前測定',SAFETY_CHECK:'安全確認',TRIAL:'限定試行',EVALUATION:'効果評価'};byId('pilotStudyStatus').innerHTML=`<div class="coverage-quality"><strong>現在段階：${escapeHtml(labels[data.phase]||data.phase)}</strong><span>進捗 ${data.progress}%</span><span>${escapeHtml(data.message)}</span></div>${data.study?`<p>${escapeHtml(data.study.wardName)}・責任者 ${escapeHtml(data.study.owner)}・上限 ${data.study.patientLimit}人・導入前 ${escapeHtml(data.study.baselineStart)}～${escapeHtml(data.study.baselineEnd)}・試行 ${escapeHtml(data.study.trialStart)}～${escapeHtml(data.study.trialEnd)}</p>`:''}`;if(data.study){const form=byId('pilotStudyForm');for(const key of ['wardName','owner','patientLimit','baselineStart','baselineEnd','trialStart','trialEnd','note'])form.elements[key].value=data.study[key]??'';}}
